// The store's own drawing (mesh.h): triangles staged on the CPU, then copied once into GPU memory.

#include "mesh.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "store_shaders.h" // generated by store_shaders.py
#include "xsdk/gpu.h"
#include "xsdk/log.h"
#include "xsdk/shader.h"

enum {
	VERTEX_FLOATS = 3 + 3 + 4 + 4, // position, normal, colour, material weights
	STRIDE_BYTES = VERTEX_FLOATS * 4,
	MAX_VERTICES = 65536,
	QUAD_VERTICES = 6,
};

static const float shadow_lift = 0.005f; // above the floor, so that the depth test keeps it
static const float shadow_strength = 0.45f;

static XsdkShader vertex_shader, pixel_shader, shadow_shader;
static float *staging;
static uint32_t vertex_count;
static volatile uint32_t *vertices;
static MeshRange shadow_quad;
static XsdkDepthStencilState opaque_depth, test_only, no_depth;
static XsdkBlendState alpha_blend, no_blend;

void mesh_lighting(float out[MESH_LIGHT_VECTORS][4], const XsdkAvatarLight *light, const float axes[3][3])
{
	memset(out, 0, sizeof(float) * 4 * MESH_LIGHT_VECTORS);
	const float *d = light->direction;
	const float length = sqrtf(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
	for (uint32_t k = 0; k < 3; k++) {
		out[0][k] = d[k] / length;
		out[1][k] = light->color[k];
		out[2][k] = light->sky[k];
		out[3][k] = light->ground[k];
		out[4][k] = axes[0][k];
		out[5][k] = axes[1][k];
		out[6][k] = axes[2][k];
	}
	out[0][3] = light->wrap;
	out[1][3] = light->highlight;
}

static bool load(XsdkShader *shader, const AvatarShaderCode *code)
{
	const NTSTATUS status = xsdk_shader_load(shader, code->container, code->container_bytes);
	if (!NT_SUCCESS(status))
		xsdk_log_write("store: shader load failed: 0x%08X", (unsigned)status);
	return NT_SUCCESS(status);
}

static void make_states(void)
{
	const XsdkDepthStencil opaque = { .depth_test = true, .depth_write = true, .depth_compare = XSDK_COMPARE_LESS_EQUAL };
	const XsdkDepthStencil tested = { .depth_test = true, .depth_write = false, .depth_compare = XSDK_COMPARE_LESS_EQUAL };
	const XsdkDepthStencil none = { .depth_test = false, .depth_write = false, .depth_compare = XSDK_COMPARE_ALWAYS };
	xsdk_gpu_depth_stencil_state(&opaque_depth, &opaque);
	xsdk_gpu_depth_stencil_state(&test_only, &tested);
	xsdk_gpu_depth_stencil_state(&no_depth, &none);
	const XsdkBlend over = { .color_source = XSDK_BLEND_SRC_ALPHA,
		.color_dest = XSDK_BLEND_ONE_MINUS_SRC_ALPHA,
		.color_op = XSDK_BLEND_OP_ADD,
		.alpha_source = XSDK_BLEND_ONE,
		.alpha_dest = XSDK_BLEND_ZERO,
		.alpha_op = XSDK_BLEND_OP_ADD,
		.write_mask = XSDK_WRITE_ALL };
	const XsdkBlend off = { .color_source = XSDK_BLEND_ONE,
		.color_dest = XSDK_BLEND_ZERO,
		.color_op = XSDK_BLEND_OP_ADD,
		.alpha_source = XSDK_BLEND_ONE,
		.alpha_dest = XSDK_BLEND_ZERO,
		.alpha_op = XSDK_BLEND_OP_ADD,
		.write_mask = XSDK_WRITE_ALL };
	xsdk_gpu_blend_state(&alpha_blend, &over);
	xsdk_gpu_blend_state(&no_blend, &off);
}

bool mesh_open(void)
{
	if (!load(&vertex_shader, &store_vertex) || !load(&pixel_shader, &store_pixel) ||
		!load(&shadow_shader, &shadow_pixel))
		return false;
	// Locations as xost maps them: 0 position, 1 colour (the normal), 2 and 3 texture coordinates 0 and 1 (the
	// colour and the material).
	const XsdkVertexElement layout[] = {
		{ .usage = XSDK_USAGE_POSITION, .format = XSDK_VERTEX_FLOAT3, .offset_bytes = 0 },
		{ .usage = XSDK_USAGE_COLOR, .format = XSDK_VERTEX_FLOAT3, .offset_bytes = 12 },
		{ .usage = XSDK_USAGE_TEXCOORD, .usage_index = 0, .format = XSDK_VERTEX_FLOAT4, .offset_bytes = 24 },
		{ .usage = XSDK_USAGE_TEXCOORD, .usage_index = 1, .format = XSDK_VERTEX_FLOAT4, .offset_bytes = 40 },
	};
	const NTSTATUS status = xsdk_shader_set_vertex_layout(
		&vertex_shader, layout, sizeof layout / sizeof layout[0], (const uint32_t[]){ STRIDE_BYTES });
	staging = NT_SUCCESS(status) ? malloc((size_t)MAX_VERTICES * STRIDE_BYTES) : NULL;
	if (!staging) {
		xsdk_log_write("store: mesh setup failed: 0x%08X", (unsigned)status);
		return false;
	}
	make_states();
	// The shadow's quad: a unit square round the origin, placed and scaled when drawn.
	const uint32_t mark = mesh_mark();
	const float black[4] = { 0, 0, 0, 1 };
	mesh_quad((const float[]){ -1, 0, 1 }, (const float[]){ 2, 0, 0 }, (const float[]){ 0, 0, -2 }, black,
		MATERIAL_PLAIN);
	shadow_quad = mesh_since(mark);
	return true;
}

void mesh_close(void)
{
	if (vertices)
		xsdk_gpu_free(vertices);
	vertices = NULL;
	free(staging);
	staging = NULL;
	xsdk_shader_free(&shadow_shader);
	xsdk_shader_free(&pixel_shader);
	xsdk_shader_free(&vertex_shader);
}

uint32_t mesh_mark(void)
{
	return vertex_count;
}

MeshRange mesh_since(uint32_t mark)
{
	return (MeshRange){ .first = mark, .count = vertex_count - mark };
}

static void put_vertex(const float *p, const float *n, const float *color, uint32_t material)
{
	if (!staging || vertex_count == MAX_VERTICES)
		return;
	float *v = staging + (size_t)vertex_count * VERTEX_FLOATS;
	memcpy(v, p, 3 * sizeof(float));
	memcpy(v + 3, n, 3 * sizeof(float));
	memcpy(v + 6, color, 4 * sizeof(float));
	for (uint32_t k = 0; k < 4; k++)
		v[10 + k] = material == MATERIAL_FLOOR + k ? 1.0f : 0.0f;
	vertex_count++;
}

void mesh_quad4(const float *p0, const float *p1, const float *p2, const float *p3, const float *normal,
	const float color[4], uint32_t material)
{
	const float *corners[QUAD_VERTICES] = { p0, p1, p2, p0, p2, p3 };
	for (uint32_t i = 0; i < QUAD_VERTICES; i++)
		put_vertex(corners[i], normal, color, material);
}

void mesh_quad(const float a[3], const float u[3], const float v[3], const float color[4], uint32_t material)
{
	float n[3] = { u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0] };
	const float length = sqrtf(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);
	float p[4][3];
	for (uint32_t k = 0; k < 3; k++) {
		n[k] = length > 0.0f ? n[k] / length : 0.0f;
		p[0][k] = a[k];
		p[1][k] = a[k] + u[k];
		p[2][k] = a[k] + u[k] + v[k];
		p[3][k] = a[k] + v[k];
	}
	mesh_quad4(p[0], p[1], p[2], p[3], n, color, material);
}

void mesh_box(const float min[3], const float max[3], const float color[4], uint32_t material)
{
	const float dx = max[0] - min[0], dy = max[1] - min[1], dz = max[2] - min[2];
	mesh_quad((const float[]){ min[0], max[1], max[2] }, (const float[]){ dx, 0, 0 }, (const float[]){ 0, 0, -dz },
		color, material); // top
	mesh_quad((const float[]){ min[0], min[1], min[2] }, (const float[]){ dx, 0, 0 }, (const float[]){ 0, 0, dz },
		color, material); // bottom
	mesh_quad((const float[]){ min[0], min[1], max[2] }, (const float[]){ dx, 0, 0 }, (const float[]){ 0, dy, 0 },
		color, material); // front, +z
	mesh_quad((const float[]){ max[0], min[1], min[2] }, (const float[]){ -dx, 0, 0 }, (const float[]){ 0, dy, 0 },
		color, material); // back, -z
	mesh_quad((const float[]){ min[0], min[1], min[2] }, (const float[]){ 0, 0, dz }, (const float[]){ 0, dy, 0 },
		color, material); // -x
	mesh_quad((const float[]){ max[0], min[1], max[2] }, (const float[]){ 0, 0, -dz }, (const float[]){ 0, dy, 0 },
		color, material); // +x
}

static void store_float(volatile uint32_t *word, float value)
{
	uint32_t bits;
	memcpy(&bits, &value, 4);
	*word = bits;
}

bool mesh_upload(void)
{
	vertices = xsdk_gpu_alloc(vertex_count * STRIDE_BYTES);
	if (!vertices) {
		xsdk_log_write("store: no GPU memory for %u vertices", (unsigned)vertex_count);
		return false;
	}
	for (size_t i = 0; i < (size_t)vertex_count * VERTEX_FLOATS; i++)
		store_float(vertices + i, staging[i]);
	__asm__ volatile("sync" ::: "memory");
	xsdk_gpu_invalidate(xsdk_gpu_address(vertices), vertex_count * STRIDE_BYTES);
	free(staging);
	staging = NULL;
	xsdk_log_write("store: %u vertices, %u KB", (unsigned)vertex_count,
		(unsigned)(vertex_count * STRIDE_BYTES / 1024));
	return true;
}

static void write_literals(const AvatarShaderCode *code, bool vertex)
{
	for (uint32_t i = 0; i < code->literal_count; i++) {
		if (vertex)
			xsdk_gpu_set_vertex_constants(code->literals[i].reg, code->literals[i].values, 1);
		else
			xsdk_gpu_set_pixel_constants(code->literals[i].reg, code->literals[i].values, 1);
	}
}

// The shaders, their literals, the vertex constants (vp, then place: moved by x, y, z, scaled by w), the range.
static void use(const XsdkShader *pixel, const AvatarShaderCode *code, const float vp[16], const float place[4],
	MeshRange range)
{
	xsdk_gpu_set_shaders(&vertex_shader, pixel);
	write_literals(&store_vertex, true);
	write_literals(code, false);
	float push[5][4];
	memcpy(push[0], vp, 16 * sizeof(float));
	memcpy(push[4], place, 4 * sizeof(float));
	xsdk_gpu_set_vertex_constants(store_vertex.push_register, push[0], 5);
	xsdk_gpu_set_vertices(0, xsdk_gpu_address(vertices) + range.first * STRIDE_BYTES, range.count * STRIDE_BYTES);
}

void mesh_use_opaque(void)
{
	xsdk_gpu_set_blend(&no_blend);
	xsdk_gpu_set_depth_stencil(&opaque_depth);
}

void mesh_draw(MeshRange range, const float vp[16], const float light[MESH_LIGHT_VECTORS][4], uint32_t mode)
{
	mesh_draw_placed(range, vp, light, mode, (const float[]){ 0, 0, 0, 1 });
}

void mesh_draw_placed(MeshRange range, const float vp[16], const float light[MESH_LIGHT_VECTORS][4], uint32_t mode,
	const float place[4])
{
	if (!range.count)
		return;
	use(&pixel_shader, &store_pixel, vp, place, range);
	xsdk_gpu_set_pixel_constants(store_pixel.push_register, light[0], MESH_LIGHT_VECTORS);
	if (mode != MESH_OPAQUE) {
		xsdk_gpu_set_blend(&alpha_blend);
		xsdk_gpu_set_depth_stencil(mode == MESH_OVERLAY ? &no_depth : &test_only);
	}
	xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST, range.count);
	if (mode != MESH_OPAQUE)
		mesh_use_opaque();
}

void mesh_draw_shadow(const float vp[16], float x, float z, float radius)
{
	use(&shadow_shader, &shadow_pixel, vp, (const float[]){ x, shadow_lift, z, radius }, shadow_quad);
	const float constants[2][4] = { { x, 0, z, radius }, { 0, 0, 0, shadow_strength } };
	xsdk_gpu_set_pixel_constants(shadow_pixel.push_register, constants[0], 2);
	xsdk_gpu_set_blend(&alpha_blend);
	xsdk_gpu_set_depth_stencil(&test_only);
	xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST, shadow_quad.count);
	mesh_use_opaque();
}
